// Parse query parameters
const query = $input.first().json.query || {};
const runId = query.run_id || '';
const projectRoot = query.project_root || '/home/shash/work/Footnote';

if (!runId) {
  return { json: { ok: false, error: 'run_id is required' } };
}

return {
  json: {
    run_id: runId,
    project_root: projectRoot,
    status_path: `${projectRoot}/workflows/project/logs/automation_runs/${runId}/status.json`
  }
};

// Parse status and return
const params = $('Parse Query').first().json;
const item = $input.first();

// Check if file read failed (file not found)
if (item.error || !item.binary || !item.binary.data) {
  return { json: { ok: false, error: 'status_not_found', run_id: params.run_id } };
}

try {
  // Convert base64 to string and parse JSON
  const jsonString = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  const status = JSON.parse(jsonString);
  return { json: { ok: true, run_id: params.run_id, status } };
} catch (e) {
  return { json: { ok: false, error: 'parse_error', run_id: params.run_id, detail: e.message } };
}
